from sys import stdin, stdout

def read_int():
    return int(stdin.readline().strip())

def read_line():
    return stdin.readline().strip()

def calculate_efficiency_gap(w_a, w_b, v):
    return abs(w_a - w_b) / float(v)

def main():
    p, d = map(read_int, read_line().split())
    precincts = []

    for _ in range(p):
        district, a, b = map(int, read_line().split())
        precincts.append((district, a, b))

    districts_won_by_A = [0] * (d + 1)
    districts_won_by_B = [0] * (d + 1)
    wasted_votes_A = 0
    wasted_votes_B = 0

    for district, a, b in precincts:
        if a > b:
            districts_won_by_A[district] += 1
            wasted_votes_B += b
            if a > b + (p // 2) + 1:
                wasted_votes_A += a - (b + (p // 2) + 1)
        else:
            districts_won_by_B[district] += 1
            wasted_votes_A += a
            if b > a + (p // 2) + 1:
                wasted_votes_B += b - (a + (p // 2) + 1)

    for i in range(1, d + 1):
        if districts_won_by_A[i] > districts_won_by_B[i]:
            stdout.write('A\n')
        elif districts_won_by_A[i] < districts_won_by_B[i]:
            stdout.write('B\n')
        else:
            stdout.write('A\n')

        stdout.write(f"{wasted_votes_A} {wasted_votes_B}\n")

    efficiency_gap = calculate_efficiency_gap(wasted_votes_A, wasted_votes_B, p)
    stdout.write(f"{efficiency_gap:.12f}\n")

if __name__ == "__main__":
    main()
